// Cross-validation tests: verify generated TypeScript functions match Rust logic.
//
// The fixture (cross-validation-fixture.json) is generated by Rust with exhaustive
// input→output mappings from the real Rust functions. This test calls the generated
// TypeScript functions with the same inputs and asserts identical outputs.
//
// If these tests fail, the TS string template in generate_typescript() has drifted
// from the Rust implementation.

import { describe, it, expect } from 'vitest';
import { availableThreadActions, displaySection, threadIsDeletable, THREAD_STATUSES } from './thread-lifecycle';
import type { ThreadType, ThreadStatus, ArchiveState, Action, DisplaySection } from './thread-lifecycle';
import fixture from './cross-validation-fixture.json';

interface AvailableThreadActionsCase {
  fn: 'availableThreadActions';
  args: [string, string, string, boolean, boolean, boolean, boolean, boolean];
  expected: string[];
}

interface DisplaySectionCase {
  fn: 'displaySection';
  args: [string, string, boolean, boolean, boolean, boolean];
  expected: string;
}

interface ThreadIsDeletableCase {
  fn: 'threadIsDeletable';
  args: [string, string, boolean, boolean, boolean];
  expected: boolean;
}

type TestCase = AvailableThreadActionsCase | DisplaySectionCase | ThreadIsDeletableCase;

// Meta-test: every generated function with logic (not just data lookups) must have
// cross-validation cases in the fixture. If you add a new function to generate_typescript()
// that has branching logic, add it to this set AND to generate_cross_validation_fixture().
const FUNCTIONS_REQUIRING_CROSS_VALIDATION = new Set(['availableThreadActions', 'displaySection', 'threadIsDeletable']);

describe('Cross-validation: generated TS matches Rust', () => {
  const cases = fixture.cases as TestCase[];

  describe('availableThreadActions', () => {
    const availableThreadActionsCases = cases.filter((c): c is AvailableThreadActionsCase => c.fn === 'availableThreadActions');

    it(`has exhaustive coverage (${availableThreadActionsCases.length} cases)`, () => {
      // 2 threadTypes × N statuses × 2 sections × 2 pending ×
      // 2 descendantsBlockArchive × 2 hasLiveEventWaits × 2 hasUnsentDraft ×
      // 2 isSaved.
      // Derived from THREAD_STATUSES rather than hardcoded, because the literal
      // product went stale on every new ThreadStatus variant.
      expect(availableThreadActionsCases.length).toBe(2 * THREAD_STATUSES.length * 2 ** 6);
    });

    for (const tc of availableThreadActionsCases) {
      const [threadType, status, section, pending, descendantsBlockArchive, waits, hasUnsentDraft, isSaved] = tc.args;
      const label = `(${threadType}, ${status}, ${section}, pending=${pending}, dba=${descendantsBlockArchive}, waits=${waits}, draft=${hasUnsentDraft}, saved=${isSaved})`;

      it(`${label} → [${tc.expected.join(', ')}]`, () => {
        const result = availableThreadActions(
          threadType as ThreadType,
          status as ThreadStatus,
          section as ArchiveState,
          pending,
          descendantsBlockArchive,
          waits,
          hasUnsentDraft,
          isSaved,
        );
        expect(result).toEqual(tc.expected as Action[]);
      });
    }
  });

  describe('displaySection', () => {
    const displaySectionCases = cases.filter((c): c is DisplaySectionCase => c.fn === 'displaySection');

    it(`has exhaustive coverage (${displaySectionCases.length} cases)`, () => {
      // 2 sections × N statuses × 2 saved × 2 activeChildren × 2 pending ×
      // 2 attentionDescendants. Derived, same reason as above.
      expect(displaySectionCases.length).toBe(2 * THREAD_STATUSES.length * 2 ** 4);
    });

    for (const tc of displaySectionCases) {
      const [section, status, saved, activeChildren, pending, attention] = tc.args;
      const label = `(${section}, ${status}, saved=${saved}, active=${activeChildren}, pending=${pending}, attention=${attention})`;

      it(`${label} → ${tc.expected}`, () => {
        const result = displaySection(
          section as ArchiveState,
          status as ThreadStatus,
          saved,
          activeChildren,
          pending,
          attention,
        );
        expect(result).toBe(tc.expected as DisplaySection);
      });
    }
  });

  describe('threadIsDeletable', () => {
    const deletableCases = cases.filter((c): c is ThreadIsDeletableCase => c.fn === 'threadIsDeletable');

    it(`has exhaustive coverage (${deletableCases.length} cases)`, () => {
      // 2 threadTypes × N statuses × 2 pending × 2 externalRepo ×
      // 2 descendantsBlock. No section dimension: delete is offered in the
      // Archive section too, which is the predicate's whole point.
      expect(deletableCases.length).toBe(2 * THREAD_STATUSES.length * 2 ** 3);
    });

    for (const tc of deletableCases) {
      const [threadType, status, pending, externalRepo, descendantsBlock] = tc.args;
      const label = `(${threadType}, ${status}, pending=${pending}, external=${externalRepo}, blocked=${descendantsBlock})`;

      it(`${label} → ${tc.expected}`, () => {
        const result = threadIsDeletable(
          threadType as ThreadType,
          status as ThreadStatus,
          pending,
          externalRepo,
          descendantsBlock,
        );
        expect(result).toBe(tc.expected);
      });
    }
  });

  describe('coverage meta-test', () => {
    it('every function requiring cross-validation has test cases in fixture', () => {
      const coveredFunctions: Set<string> = new Set(cases.map(c => c.fn));
      for (const fn of FUNCTIONS_REQUIRING_CROSS_VALIDATION) {
        expect(coveredFunctions.has(fn), `Missing cross-validation cases for '${fn}'`).toBe(true);
      }
    });

    it('no unexpected functions in fixture without validation requirement', () => {
      const coveredFunctions: Set<string> = new Set(cases.map(c => c.fn));
      for (const fn of coveredFunctions) {
        expect(
          FUNCTIONS_REQUIRING_CROSS_VALIDATION.has(fn),
          `Fixture has cases for '${fn}' but it's not in FUNCTIONS_REQUIRING_CROSS_VALIDATION`,
        ).toBe(true);
      }
    });
  });
});
